// Preserve the source verbatim and normalize only the working copy.
for (const item of $input.all()) {
  const j = item.json;
  const original = typeof j.Ticket === 'string' ? j.Ticket : JSON.stringify(j.Ticket ?? j);
  let schema = j['JSON Extract'] ?? {};
  if (typeof schema === 'string') {
    try { schema = JSON.parse(schema); }
    catch (e) { throw new Error('JSON Extract is not valid JSON: ' + e.message); }
  }
  if (!original.trim()) throw new Error('Ticket source is empty');
  if (!schema || typeof schema !== 'object' || Array.isArray(schema)) throw new Error('JSON Extract must be a JSON object');
  j.original_source = original;
  j.normalized_text = original.replace(/\r\n/g, '\n').replace(/[\t ]+/g, ' ').trim();
  j.extraction_schema = schema;
  j.received_at = new Date().toISOString();
}
return $input.all();

const items = $input.all();

const REQUIRED_FIELDS = [
  'requester',
  'ticket_id',
  'email',
  'device',
  'assigned_engineer',
  'error_message',
  'affected_applications',
  'attempted_fixes',
  'callback_time',
];

const LIST_FIELDS = [
  'affected_applications',
  'attempted_fixes',
];

for (const item of items) {
  const j = item.json;

  // Clocked Extract returns fields as:
  // { requester: { value, confidence }, ... }
  // Support both the actual "fields" format and a flat extraction object.
  let raw =
    j.extracted_data ??
    j.extracted ??
    j.fields ??
    j.result ??
    j.data ??
    j.output;

  if (typeof raw === 'string') {
    try {
      raw = JSON.parse(raw);
    } catch {
      j.extraction_error = 'Extraction response was not valid JSON';
      raw = null;
    }
  }

  // Unwrap common response wrappers if necessary.
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    if (
      raw.fields &&
      typeof raw.fields === 'object' &&
      !Array.isArray(raw.fields)
    ) {
      raw = raw.fields;
    } else if (
      raw.extracted_data &&
      typeof raw.extracted_data === 'object' &&
      !Array.isArray(raw.extracted_data)
    ) {
      raw = raw.extracted_data;
    }
  }

  const missing = [];
  const invalid = [];
  const extracted = {};

  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    j.extraction_error =
      j.extraction_error || 'No object-like extraction payload found';
  } else {
    for (const key of REQUIRED_FIELDS) {
      const field = raw[key];

      // Clocked fields are normally objects containing "value".
      const value =
        field &&
        typeof field === 'object' &&
        !Array.isArray(field) &&
        Object.prototype.hasOwnProperty.call(field, 'value')
          ? field.value
          : field;

      // Preserve legitimate optional values separately below.
      if (
        value === undefined ||
        value === null ||
        (typeof value === 'string' && value.trim() === '')
      ) {
        missing.push(key);
        continue;
      }

      if (LIST_FIELDS.includes(key)) {
        if (!Array.isArray(value)) {
          invalid.push(`${key}_must_be_array`);
          continue;
        }

        const cleaned = value.filter(
          v => typeof v === 'string' && v.trim() !== ''
        );

        if (cleaned.length !== value.length) {
          invalid.push(`${key}_contains_invalid_items`);
        }

        extracted[key] = cleaned;
      } else {
        if (typeof value !== 'string') {
          invalid.push(`${key}_must_be_string`);
          continue;
        }

        extracted[key] = value.trim();
      }
    }

    // Validate email format.
    if (
      extracted.email &&
      !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(extracted.email)
    ) {
      invalid.push('email_invalid_format');
    }

    // Optional field: null is acceptable when no estimate exists.
    const estimateField = raw.restoration_estimate;
    const estimate =
      estimateField &&
      typeof estimateField === 'object' &&
      !Array.isArray(estimateField) &&
      Object.prototype.hasOwnProperty.call(estimateField, 'value')
        ? estimateField.value
        : estimateField;

    extracted.restoration_estimate =
      estimate === undefined || estimate === null ||
      (typeof estimate === 'string' && estimate.trim() === '')
        ? null
        : estimate;

    // Preserve field-level confidence for downstream review/auditing.
    const fieldConfidence = {};

    for (const [key, field] of Object.entries(raw)) {
      if (
        field &&
        typeof field === 'object' &&
        !Array.isArray(field) &&
        typeof field.confidence === 'number'
      ) {
        fieldConfidence[key] = field.confidence;
      }
    }

    j.extracted_fields = extracted;
    j.extraction_confidence = fieldConfidence;
  }

  const valid =
    !j.extraction_error &&
    missing.length === 0 &&
    invalid.length === 0;

  j.extraction_validation = {
    valid,
    missing_fields: missing,
    invalid_fields: invalid,
  };

  j.human_review_required = !valid;
}

return items;

const MIN_CONFIDENCE = 0.85;

for (const item of $input.all()) {
  const j = item.json;

  let d =
    j.decision_result ??
    j.decision ??
    j.result ??
    j.data ??
    j.output;

  if (typeof d === 'string') {
    try {
      d = JSON.parse(d);
    } catch (_) {
      d = null;
    }
  }

  // Support answers returned through different response structures.
  const answers = d?.answers ?? d?.questions ?? d ?? {};

  const categoryAnswer = answers.ticket_category;
  const urgencyAnswer = answers.urgency;
  const reviewAnswer = answers.requires_human_review;

  const category =
    typeof categoryAnswer === 'string'
      ? categoryAnswer.trim() || null
      : (
          categoryAnswer?.value ??
          categoryAnswer?.answer ??
          categoryAnswer?.choice ??
          null
        );

  const confidenceRaw =
    categoryAnswer?.confidence ??
    categoryAnswer?.probability ??
    categoryAnswer?.score ??
    d?.confidence;

  const confidence =
    typeof confidenceRaw === 'number'
      ? confidenceRaw
      : (
          typeof confidenceRaw === 'string' &&
          confidenceRaw.trim() !== ''
            ? Number(confidenceRaw)
            : null
        );

  const explicitReview =
    reviewAnswer === 'yes' ||
    reviewAnswer?.value === 'yes' ||
    reviewAnswer?.answer === 'yes' ||
    reviewAnswer?.choice === 'yes';

  const hasConflict = Boolean(
    j.extraction_validation?.valid === false ||
    j.conflict_detected ||
    j.extraction_error
  );

  const reasons = [];

  if (j.extraction_validation?.valid !== true) {
    reasons.push('extraction_validation_failed');
  }

  // Generic validation: no predefined category allowlist.
  if (
    typeof category !== 'string' ||
    category.trim() === ''
  ) {
    reasons.push('category_missing');
  }

  if (
    confidence === null ||
    !Number.isFinite(confidence) ||
    confidence < 0 ||
    confidence > 1
  ) {
    reasons.push('confidence_missing_or_invalid');
  } else if (confidence < MIN_CONFIDENCE) {
    reasons.push('confidence_below_threshold');
  }

  if (explicitReview) {
    reasons.push('model_requested_human_review');
  }

  if (hasConflict) {
    reasons.push('conflicting_or_invalid_source_data');
  }

  const urgency =
    typeof urgencyAnswer === 'string'
      ? urgencyAnswer
      : (
          urgencyAnswer?.value ??
          urgencyAnswer?.answer ??
          urgencyAnswer?.choice ??
          null
        );

  j.decision_summary = {
    category,
    urgency,
    confidence,
    threshold: MIN_CONFIDENCE,
    human_review_required: reasons.length > 0,
    review_reasons: [...new Set(reasons)],
    raw_decision: d ?? null,
  };

  j.update_approved = reasons.length === 0;

  j.audit_record = {
    correlation_id: j.correlation_id,
    ticket_id: j.extracted_fields?.ticket_id ?? null,
    received_at: j.received_at,
    processed_at: new Date().toISOString(),
    extraction_valid: j.extraction_validation?.valid === true,
    decision_category: category,
    decision_confidence: confidence,
    update_approved: j.update_approved,
    review_reasons: j.decision_summary.review_reasons,
  };
}

return $input.all();

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 3 | 8)).toString(16);
  });
}
for (const item of $input.all()) {
  item.json.correlation_id = item.json.correlation_id || uuid();
}
return $input.all();

